struct Creator {
    std::unique_ptr<Product> create() const { return create_product(); }
    virtual ~Creator() = default;
protected:
    virtual std::unique_ptr<Product> create_product() const = 0;
};

struct ConcreteCreator : Creator {
    std::unique_ptr<Product> create_product() const override {
        return std::make_unique<ConcreteProduct>();
    }
};

using Creator = std::function<std::unique_ptr<Shape>()>;
std::unordered_map<std::string, Creator> registry;

registry.emplace("circle", [] { return std::make_unique<Circle>(1.0); });

std::unique_ptr<Shape> make(const std::string& name) {
    auto it = registry.find(name);
    if (it == registry.end()) throw std::out_of_range(name);
    return it->second();
}
